{
  "name": "opencode-chrome",
  "version": "0.2.0",
  "description": "MCP bridge that lets opencode drive your real Chrome via a thin MV3 extension",
  "type": "module",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/G10hdz/opencode-chrome.git"
  },
  "bugs": "https://github.com/G10hdz/opencode-chrome/issues",
  "homepage": "https://github.com/G10hdz/opencode-chrome#readme",
  "keywords": [
    "mcp",
    "opencode",
    "chrome",
    "browser-automation",
    "cdp"
  ],
  "files": [
    "src",
    "README.md",
    "LICENSE"
  ],
  "bin": {
    "opencode-chrome": "src/index.js"
  },
  "scripts": {
    "test": "node scripts/check-manifest.js && node --test",
    "pack": "node scripts/check-manifest.js && bash scripts/pack-extension.sh",
    "prepublishOnly": "npm test",
    "test:e2e": "playwright test --config=e2e/playwright.config.mjs"
  },
  "engines": {
    "node": ">=20"
  },
  "dependencies": {
    "@modelcontextprotocol/sdk": "^1.12.0",
    "ws": "^8.18.0",
    "zod": "^3.25.0"
  },
  "devDependencies": {
    "@playwright/test": "1.63.0"
  }
}
